class MyInput extends HTMLElement {
  static get formAssociated() { return true; } // Участвует в формах!

  constructor() {
    super();
    this.internals = this.attachInternals();
    this._value = '';
  }

  get value() { return this._value; }
  set value(v) {
    this._value = v;
    this.internals.setFormValue(v); // Устанавливает значение для form submit
  }

  // Validation:
  checkValidity() { return this.internals.checkValidity(); }
  reportValidity() { return this.internals.reportValidity(); }
  setValidity(flags, message) { this.internals.setValidity(flags, message); }
}

customElements.define('my-input', MyInput);

